// Build the human-facing question. The resume URL belongs to THIS execution:
// opening it renders an n8n form, and submitting it resumes the Wait node below
// with the typed answer.
//
// Written to the message contract (notification-taxonomy.md): the TITLE states
// what is blocked, the ACTION line says what the reader must do, and the detail
// follows. A question that buries the ask under context gets skimmed past.
const i = $input.first().json || {};
const NL = String.fromCharCode(10);
// resumeFormUrl, NOT resumeUrl. With resume:"form" the form is served at
// /form-waiting/<id> while $execution.resumeUrl points at /webhook-waiting/<id>.
// The wrong one does not merely 404 — hitting the webhook URL RESUMES the wait
// with no submitted data, so a human who clicked it would unblock the agent
// while answering nothing. Verified against a live waiting execution.
const url = $execution.resumeFormUrl;
const q = (i.question || '').trim();

if (!q) {
  // An empty question would render a form asking nothing, and a human would
  // answer it with nothing. Fail loudly at the seam instead.
  throw new Error('ask-question called with no `question` — refusing to ask a human nothing.');
}

const hours = Number(i.timeoutHours) > 0 ? Number(i.timeoutHours) : 24;

return [{ json: {
  severity: 'warn',
  title: `Agent is blocked: ${q.slice(0, 90)}`,
  action: `Answer to unblock — ${url}`,
  metric: `waiting up to ${hours}h`,
  message: [
    i.context ? `Context: ${i.context}` : '',
    '',
    `Open to answer: ${url}`,
    '',
    `_No answer within ${hours}h returns "unanswered" to the agent — NOT an` +
    ` empty answer, and NOT approval of anything._`,
  ].filter(Boolean).join(NL),
  source: i.source || 'ask-question',
  runUrl: url,
  _question: q,
  _hours: hours,
} }];

// Resumed either by a submitted form or by the timeout.
//
// THE DISTINCTION THAT MATTERS: "nobody answered" and "answered with nothing"
// must never collapse into the same value. A caller that cannot tell them apart
// will treat silence as an empty-but-valid fact and carry on — which is exactly
// the guessing this control exists to stop. So `answered` is a separate boolean
// from `answer`, and a timeout sets answered=false.
const j = $input.first().json || {};

// n8n form resumes put submitted fields at the top level, keyed by field label.
// Accept a couple of shapes rather than assuming one, and say so if none match.
const raw = (typeof j.Answer === 'string') ? j.Answer
          : (typeof j.answer === 'string') ? j.answer
          : (j.data && typeof j.data.Answer === 'string') ? j.data.Answer
          : null;

const answer = (raw || '').trim();
const answered = raw !== null && answer.length > 0;

return [{ json: {
  answered,
  answer,
  timedOut: raw === null,
  // Present so a caller can log WHY it proceeded without an answer rather than
  // silently defaulting.
  // Name the FIELDS WE SAW when nothing parsed. Without this the failure reads
  // as "the human submitted nothing" when the real cause may be a field-name
  // mismatch — two very different problems that looked identical, and cost real
  // debugging time. Keys only, never values: this string reaches a channel.
  note: answered ? 'human answered'
      : (raw === null ? 'no response before the timeout — treat as UNKNOWN, not as empty'
                      : 'form returned no usable answer — treat as UNKNOWN. fields seen: ' +
                        (Object.keys(j).join(', ') || '(none)')),
} }];
